import re


class Router:
    """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns (handler, params)
    for a path or (None, {}) when nothing matches.
    """

    def __init__(self):
        self._routes = []

    def add(self, path, handler):
        self._routes.append((path, handler))

    def resolve(self, path):
        # First pass: static routes always win over dynamic routes,
        # regardless of registration order.
        for route, handler in self._routes:
            if '<' not in route and '>' not in route:
                if route == path:
                    return handler, {}

        # Second pass: parameterized routes.
        for route, handler in self._routes:
            if '<' in route and '>' in route:
                result = self._match(route, path)
                if result is not None:
                    return handler, result

        return None, {}

    def _match(self, route, path):
        """Match a parameterized route against a path.

        Returns the captured params dict, or None if no match.
        """
        route_segments = route.split('/')
        path_segments = path.split('/')

        if len(route_segments) != len(path_segments):
            return None

        params = {}
        for r_seg, p_seg in zip(route_segments, path_segments):
            match = re.match(r'^<(\w+)>$', r_seg)
            if match:
                # This is a parameter segment
                if not p_seg:
                    # Empty segment must not satisfy a parameter
                    return None
                params[match.group(1)] = p_seg
            else:
                # Static segment must match exactly
                if r_seg != p_seg:
                    return None

        return params

