class Router:
    """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns (handler, params)
    for a path or (None, {}) when nothing matches.

    Supports parameterized path segments written as `<name>`, e.g.
    `/jobs/<job_id>/runs/<run_id>`.
    """

    def __init__(self):
        self._static_routes = []  # (path, handler)
        self._dynamic_routes = []  # (path_template, handler, segments)

    def add(self, path, handler):
        if '<' in path and '>' in path:
            # Dynamic route
            segments = path.split('/')
            self._dynamic_routes.append((path, handler, segments))
        else:
            # Static route
            self._static_routes.append((path, handler))

    def _match_dynamic(self, path, segments):
        """Try to match a path against a dynamic route's segments.
        Returns a dict of captured values or None if no match."""
        path_parts = path.split('/')
        if len(path_parts) != len(segments):
            return None
        params = {}
        for path_part, segment in zip(path_parts, segments):
            if segment.startswith('<') and segment.endswith('>'):
                # Parameterized segment
                name = segment[1:-1]
                if not path_part:  # empty segment must not satisfy a parameter
                    return None
                params[name] = path_part
            else:
                if path_part != segment:
                    return None
        return params

    def resolve(self, path):
        # First, try static routes (exact match, first registered wins)
        for route, handler in self._static_routes:
            if route == path:
                return handler, {}

        # Then, try dynamic routes (exact segment count match)
        # We need to ensure static routes win over dynamic routes
        # that also match. Since we already checked static routes above,
        # any dynamic route match is fine.
        for path_template, handler, segments in self._dynamic_routes:
            params = self._match_dynamic(path, segments)
            if params is not None:
                return handler, params

        return None, {}

