        self.clock = clock
        self.max_size = max_size
        self._data = OrderedDict()

    def set(self, key, value):
        if key in self._data:
            # Update existing key in place (move to end for LRU)
            self._data.move_to_end(key)
            self._data[key] = (value, self.clock())
        else:
            self._data[key] = (value, self.clock())
            # Evict least recently used if over max_size (and max_size > 0)
            if self.max_size is not None and self.max_size > 0:
                while len(self._data) > self.max_size:
                    self._data.popitem(last=False)

    def get(self, key, default=None):
        if key not in self._data:
            return default
        value, stamp = self._data[key]
        if self.clock() - stamp >= self.ttl:
            del self._data[key]
            return default
        # Count as a use: move to end (most recently used)
        self._data.move_to_end(key)
        return value

    def __len__(self):
        return len(self._data)

