"""Minimal path router for the internal status service."""


class Router:
    """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns (handler, params)
    for a path or (None, {}) when nothing matches.
    """

    def __init__(self):
        self._static_routes = {}   # path -> handler (exact matches)
        self._static_order = []    # list of (path, handler) in registration order
        self._dynamic_routes = []   # list of (pattern_parts, handler)

    def add(self, path, handler):
        if "<" in path:
            # Dynamic route
            parts = path.split("/")
            self._dynamic_routes.append((parts, handler))
        else:
            # Static route — first registration wins
            if path not in self._static_routes:
                self._static_routes[path] = handler
                self._static_order.append((path, handler))

    def resolve(self, path):
        # First, check static routes (exact match) — these always win
        if path in self._static_routes:
            return self._static_routes[path], {}

        # Then try dynamic routes
        path_parts = path.split("/")
        for route_parts, handler in self._dynamic_routes:
            if len(route_parts) != len(path_parts):
                continue
            params = {}
            matched = True
            for route_part, path_part in zip(route_parts, path_parts):
                if route_part.startswith("<") and route_part.endswith(">"):
                    param_name = route_part[1:-1]
                    # Empty segment must not satisfy a parameter
                    if path_part == "":
                        matched = False
                        break
                    params[param_name] = path_part
                else:
                    if route_part != path_part:
                        matched = False
                        break
            if matched:
                return handler, params

        return None, {}
